-- ids de tabelas e campos especificos censurados


WITH insumo_original AS (
SELECT DISTINCT
    DSC_CLASSE_TERAPEUTICA__c, -- possivelmente inutil já que a classificação é feita em cima da principio ativo 
    COD_TUSS_CONSOLIDADO__c, -- codigo_tuss (outra observação é que na tabela original existem outras colunas com codigo tuss)
    DSC_PRINCIPIO_ATIVO__c, --principio ativo que vou classificar
    DSC_MEDICAMENTO_REF__c --marca talvez eu comente
FROM tab
WHERE 1=1
  AND FRM_TIPO_REGISTRO__c = 'Medicamento'
  AND CODIGO_SAS__C IS NULL
),
-- Nova CTE para normalizar o princípio ativo da insumo_original
insumo_com_pa_normalizado AS (
SELECT
    iou.DSC_CLASSE_TERAPEUTICA__c,
    iou.COD_TUSS_CONSOLIDADO__c,
    iou.DSC_PRINCIPIO_ATIVO__c AS INS_PRINCIPIO_ATIVO_ORIGINAL,
    CASE 
        WHEN UPPER(iou.DSC_PRINCIPIO_ATIVO__c) = 'RUXIENCE' THEN 'RITUXIMABE'
        WHEN UPPER(iou.DSC_PRINCIPIO_ATIVO__c) = 'IMUNOGLOBULINA G' THEN 'IMUNOGLOBULINA HUMANA'
        ELSE iou.DSC_PRINCIPIO_ATIVO__c 
    END AS INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO,
    iou.DSC_MEDICAMENTO_REF__c
FROM tab iou
),
-- Sua CTE de classificação final
nao_espec_classificacao_final AS (
SELECT
    ipan.DSC_CLASSE_TERAPEUTICA__c AS INS_DSC_CLASSE_TERAPEUTICA_ORIG,
    ipan.COD_TUSS_CONSOLIDADO__c,
    ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO,
    ipan.DSC_MEDICAMENTO_REF__c AS INS_DSC_MEDICAMENTO_REF,
    CASE -- Lógica de DSC_CLASSIFICACAO_MEDICAMENTO_NOVA da tb_class_med_final, aplicada ao INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO
        WHEN ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO IN('ABATACEPTE','ACTEMRA','ADALIMUMABE','ADCETRIS','AMGEVITA','ATEZOLIZUMABE','AVASTIN','AVELUMABE','AVONEX','AVSOLA','BACILLUS CALMETTE GUERIN LIOFILIZADO','BAVENCIO','BENLYSTA','BESPONSA','BEVACIZUMABE','BIO MANGUINHOS INFLIXIMABE','BLAUIMUNO','BLINATUMOMABE','BLINCYTO','BLYNCITO','BRENTUXIMABE','BRENZYS','CEMIPLIMABE','CETUXIMABE','CIMZIA','COSENTYX','CUVITRU','CYRAMZA','DALINVI','DARATUMUMABE','DUPIXENT','DURVALUMABE','ELOVIE','EMPLICITI','ENBREL','ENBREL PFS','ENDOBULIN KIOVIG','ENDOBULIN KIOVIG','ENHERTU','ENTYVIO','ERBITUX','ERELZI','EVUSHELD','FASENRA','FLEBOGAMMA','GAMUNEX','GAMUNEX','GAZYVA','HERCEPTIN','HERZUMA','HIZENTRA','HUMIRA','HYQVIA','HYQVIA','HYRIMOZ','IDACIO','ILARIS','IMFINZI','IMJUDO','IMUNO BCG','IMUNOGLOBULIN','IMUNOGLOBULIN','INFLIXIMABE','INTRATECT','IPILIMUMABE','ISATUXIMABE','JEMPERLI','KADCYLA','KANJINTI','KESIMPTA','KEYTRUDA','LARTRUVO','LEMTRADA','LIBTAYO','MABTHERA','MABTHERA','MABTHERA','MEPACT','MEPOLIZUMABE','MYCOBACTERIUM BOVIS','MYLOTARG','NIVOLUMABE','NUCALA','OBINUTUZUMABE','OCREVUS','OCTAGAM','OFATUMUMABE','ONCO BCG','OPDIVO','ORENCIA','PANITUMUMABE','PEMBROLIZUMABE','PENTAGLOBIN','PERJETA','PERTUZUMABE','PHESGO','ROPOLIVY','QARZIBA','REBIF','REMICADE','REMSIMA','RITUXIMABE','RITUXIMABE','RIXIMYO','RIXIMYO','RIXIMYO','RUXIENCE','RYBREVANT','SANDOGLOBULINA','SARCLISA','SECUQUINUMABE','SIMPONI','SKYRIZI','STELARA','TALTZ','TECENTRIQ','TECVAYLI','TEGELINE','TRASTUZUMABE','TRASTUZUMABE DERUXTECANO','TRASTUZUMABE ENTANSINA','TRAZIMERA','TREMFYA','TRODELVY','TRUXIMA','TRUXIMA','TYSABRI','UNITUXIN','UROHIPE BCG','USTEQUINUMABE','VACINA BCG','VECTIBIX','VEDOLIZUMABE','VIVAXXIA','VIVAXXIA','XILBRILADA','XILFYA','XOLAIR','YERVOY','ZEDORA') THEN 'IMUNOTERAPIA - IMUNOBIOLOGICO'
        WHEN ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO IN('IMNOVID','LENALIDOMIDA','NUVYOR','POMALID','POMALYST','REVLIMID') THEN 'IMUNOTERAPIA - NAO IMUNOBIOLOGICO'
        WHEN ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO IN('ACIDO ZOLEDRONICO','ACLASTA','AKYNZEO','ALFAEPOETINA','ARANESP','AREDIA','BLAZTERE','CUPRIMINE','DENOSUMABE','EPREX','ERITROMAX','ERITROPOETINA','FAULDLEUCO','FAULDPAMI','HEMAX','NETUPITANTO','ONTRAX','PROLIA','REUQUINOL','TECNOCARB','TEORO','TEPADINA','XGEVA','ZOLIBBS','ZOMETA') THEN 'MEDICAMENTO DE SUPORTE'
        WHEN ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO IN('FILGRASTIM','FILGRASTINE','FIPRIMA','FULPHILA','GRANULOKINE','LEUKINE','LIPEGFILGRASTIM','LONQUEX','NEULASTIM','PEGFILGRASTIM','PELGRAZ','TEVAGRASTIM','ZARZIO') THEN 'MEDICAMENTO DE SUPORTE IMUNOBIOLOGICO'
        WHEN ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO IN('ABRAXANE','ACIDO TRANSRETINOICO','ADRIAMICINA','ADRIBLASTINA','ALIMTA','ALKERAN','ARACYTIN','ASPARAGINASE','ATRED','AZACITIDINA','B - PLATIN','BECENUN','BENALQ','BENDAMUSTINA','BICNU','BIOEZULEN','BLENOXANE','BLEOCEL','BLEOCINS','BLEOMICINA','BLEOMYCIN','BONAR','BRECILA','BUCELON','BUSILVEX','BUSSULFANO','BUSULFEX','C - PLATIN','CAAB','CABAZITAXEL','CABAZRED','CAELYX','CAMPTOSAR','CAPECITABINA','CARBOPLATINA','CARMUSTINA','CICLOFOSFAMIDA','CISPLATEX','CISPLATINA','CITARABINA','CITARAX','CITOPLAX','CITOSTAL','CLORITECAN','COLLECTRO','CORRETAL','COSMEGEN','DACARB','DACARBAZINA','DACILON','DACOGEN','DACTINOMICINA','DAUNOBLASTINA','DAUNOCIN','DAUNORRUB','DAUNORRUBICINA','DECITABINA','DETIMEDAC','DOCELIBBS','DOCETAXEL','DOCEUNO','DOCKS','DOXOLEN','DOXOPEG','DOXORRUBICINA','ELOXATIN','EPIRRUBICINA','EPOSIDO','EROXYM','ERWINASE','ETOPOSIDEO','ETOPOSIDO','EUNADES','EVOCLASS','EVODAZIN','EVOFLUBINA','EVOLOX','EVOMID','EVOMIXAN','EVOPOSDO','EVORUBICIN','EVOTABINA','EVOTAXEL','EVOTERIN','EVOXALI','EVOZAR','EZULEN','FARMORUBICINA','FAULBLASTINA','FAULDACAR','FAULDCARBO','FAULDCISPLA','FAULDCITA','FAULDFLUOR','FAULDMETRO','FAULDOXO','FAULDVINCRI','FLUDALIBBS','FLUDARA','FLUDARABINA','FLUORURACILA','FLUSAN','GCIB','GEMCIT','GEMZAR','GENABYX','GENCITABINA','GENCIX','GENLIBBS','GENUXAL','HIDROXIUREIA','HOLOXANE','HYCAMTIN','HYDREA','HYTAS','IDA','IDARRUBICINA','IFOSFAMIDA','IRINOTECANO','IRNOCAM','IRO','JAVLOR','JEVTANA','LANVIS','LEUKERAN','LEUSTATIN','LEUX','LEVACT','LIFOS','LISODREN','LONSURF','MELFALANO','MELPHALAN','MERCAPTOPURINA','MESOTEM','METOTREXATO','METREXATO','MIANTREX','MITOCIN','MITOMICINA','MITOXANTRONA','MTX','MUPHORAN','NATULAN','NAVELBINE','NEOCITEC','NIBISNU','NORELBIN','ONCASPAR','ONCODOCEL','ONCODOX','ONCOVIN','ONIVYDE','ONTAX','OPLAT','OXA','OXALIBBS','OXALIMEIZ','OXALIPLATINA','PACLITAX','PACLITAXEL','PARAPLATIN','PAREXEL','PEGASPARGASE','PEMEGLENN','PEMETREXEDE','PEMTRYX','PLATAMINE','PLATISTINE','PLEXEDEN','PROAZITAX','PROCARBAZINA','PROTOITECAN','PURINETHOL','RABINEFIL','REDTIBIN','RIBOMUSTIN','RUBIDOX','SPECTRILA','SUKHI','TACE','TARVEXOL','TAXILAN','TAXOL','TAXOTERE','TECNOCRIS','TECNOMICINA','TECNOTECAN','TEMODAL','TEMOLIDA','TEMOZOLOMIDA','TEPEV','TEVACARBO','TEVAETOPO','TEVAMETHO','TEVAOXALI','TIOTEPA','TOPORAN','TOPOTECANA','TREBYXAN','TRETINOINA','TRIOXIDO DE ARSENIO','TRISENOX','VANCEL','VELBAN','VEPESID','VESANOID','VIDAZA','VILNE','VIMBLASTINA','VINCIZINA','VINCRISTINA','VINORELBINA','WINDUZA','XELODA','YONDELIS','ZAVEDOS') THEN 'QUIMIOTERAPICO'
        WHEN ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO IN('AFINITOR','ALECENSA','ALUNBRIG','BELEODAQ','BORTEZOMIBE','BOZORED','BRAFTOVI','BRUKINSA','CABOMETYX','CALQUENCE','CAPRELSA','CARBOMETYX','CARFILZOMIBE','CERTICAN','COTELLIC','ELOME','ERFANDEL','ERIBULINA','ERIVEDGE','EVEROLIMO','EVOBRIG','FYARRO','GIOTRIF','GLIMATIN','GLIVEC','HALAVEN','IBRANCE','ICLUSIG','IMATINIBE','IMBRUVICA','INLYTA','IRESSA','JAKAVI','KISQALI','KOSELUGO','KYPROLIS','LENVATINIBE','LENVIMA','LEUPHILA','LORBRENA','LORVIQUA','LUMAKRAS','LYNPARZA','MEKINIST','MEKTOVI','MIELOCADE','NERLYNX','NEXAVAR','NINLARO','NINTEDANIBE','OFEV','OLAPARIBE','OLUMIANT','PAZOPANIBE','PIQRAY','RETEVMO','RINVOQ','RYDAPT','SPRYCEL','STIVARGA','SUTENT','TABRECTA','TAFINLAR','TAGRISSO','TARCEVA','TASIGNA','TEPMETKO','TIBSOVO','TORISEL','TOVAR','TRAMETINIBE','TYKERB','VELCADE','VENCLEXTA','VENETOCLAX','VERAZO','VERZENIOS','VITRAKVI','VOTRIENT','WELIREG','XALKORI','XELJANZ','XOSPATA','ZALTRAP','ZEJULA','ZELBORAF','ZOMI','ZYKADIA') THEN 'TERAPIA ALVO - DROGAS SINTETICAS'
        WHEN ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO IN('ABIRATERONA','ANASTROLIBBS','ANASTROZOL','ARAZABI','ARIMIDEX','AROMASIN','BICALUTAMIDA','CASODEX','CINACALCETE','DEGARELIX','DESTILBENOL','ELIGARD','ERLEADA','EXEMESTANO','FASLODEX','FEMARA','FEMIGESTROL','FIRMAGON','FULVESTRANTO','GOSSERRELINA','LANREOTIDA','LECTRUM','LETROZOL','LEUPRORRELINA','LUPRON DEPOT','MATIZ','MEGESTAT','NEO DECAPEPTYL','NOLVADEX D','NUBEQA','OCTREOTIDA','OCTRIDE','POEMMY','PROEXTY','RARIJA','SANDOSTATIN','SELETIV','SOMATULINE','SUPRENIQ','TACFEN','TAMOXIFENO','TAMOXIM','TAXOFEN','TECNOTAX','TRIPTORRELINA','VEQUILE','XTANDI','ZOLADEX','ZOSTIDE','ZYTIGA') THEN 'TERAPIA ENDOCRINA'
        ELSE 'REVER'
    END AS INS_DSC_CLASSIFICACAO_MEDICAMENTO_NOVA,

    CASE -- Lógica de DSC_CLASSIFICACAO_VIA_ACESSO_NOVA da tb_class_med_final, aplicada ao INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO
        WHEN ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO IN('TECNOCARB','TEPADINA','LEVACT','RIBOMUSTIN','BENDAMUSTINA','BUSILVEX','BUSULFEX','BUSSULFANO','BUCELON','VANCEL','BICNU','BECENUN','NIBISNU','CARMUSTINA','DACARB','EVODAZIN','DETIMEDAC','FAULDACAR','DACARBAZINA','MUPHORAN','LIFOS','EVOLOX','HOLOXANE','IFOSFAMIDA','TEMOLIDA','TIOTEPA','CITARAX','FAULDCITA','CITARABINA','DACOGEN','REDTIBIN','DECITABINA','FLUDARA','EVOFLUBINA','FLUDALIBBS','FLUDARABINA','FLUSAN','FAULDFLUOR','FLUORURACILA','GCIB','EVOZAR','GEMCIT','GEMZAR','GENCIX','GENABYX','GENLIBBS','GENCITABINA','ATRED','SUKHI','ALIMTA','EROXYM','MESOTEM','PEMTRYX','PLEXEDEN','PEMEGLENN','PEMETREXEDE','YONDELIS','VELBAN','RABINEFIL','VIMBLASTINA','FAULBLASTINA','ONCOVIN','TECNOCRIS','VINCIZINA','FAULDVINCRI','VINCRISTINA','JAVLOR','VILNE','NEOCITEC','NORELBIN','EVOTABINA','NAVELBINE','VINORELBINA','TACE','DOCEUNO','TAXOTERE','DOCELIBBS','DOCETAXEL','ONCODOCEL','ONTAX','TAXOL','PAREXEL','TAXILAN','EVOTAXEL','PACLITAX','TARVEXOL','PACLITAXEL','ABRAXANE','CABAZRED','PROAZITAX','CABAZITAXEL','CAAB','JEVTANA','IRO','IRNOCAM','ONIVYDE','EVOTERIN','TREBYXAN','CAMPTOSAR','CLORITECAN','TECNOTECAN','IRINOTECANO','PROTOITECAN','TOPORAN','HYCAMTIN','TOPOTECANA','TEVAETOPO','BONAR','BLEOCEL','BLEOCINS','BLENOXANE','BLEOMYCIN','BLEOMICINA','TECNOMICINA','IDA','DACILON','COSMEGEN','DACTINOMICINA','DAUNOCIN','EVOCLASS','DAUNORRUB','DAUNOBLASTINA','DAUNORRUBICINA','DOCKS','DOXOLEN','ONCODOX','RUBIDOX','FAULDOXO','EVORUBICIN','ADRIAMICINA','ADRIBLASTINA','DOXORRUBICINA','CAELYX','DOXOPEG','BRECila','EPIRRUBICINA','FARMORUBICINA','EVOMID','ZAVEDOS','IDARRUBICINA','MITOCIN','MITOMICINA','EVOMIXAN','MITOXANTRONA','TORISEL','CARBOMETYX','LARTRUVO','EMPLICITI','GAZYVA','OBINUTUZUMABE','ELOVIE','AVASTIN','BEVACIZUMABE','PERJETA','PERTUZUMABE','ZEDORA','HERZUMA','KANJINTI','HERCEPTIN','TRAZIMERA','TRASTUZUMABE','TRASTUZUMABE DERUXTECANO','TRASTUZUMABE ENTANSINA','ENHERTU','KADCYLA','ERBITUX','CETUXIMABE','VECTIBIX','PANITUMUMABE','TECENTRIQ','ATEZOLIZUMABE','BAVENCIO','AVELUMABE','LIBTAYO','CEMIPLIMABE','JEMPERLI','IMFINZI','DURVALUMABE','OPDIVO','NIVOLUMABE','KEYTRUDA','PEMBROLIZUMABE','RYBREVANT','QARZIBA','BLINCYTO','BLYNCITO','BLINATUMOMABE','ADCETRIS','BRENTUXIMABE','DALINVI','DARATUMUMABE','UNITUXIN','MYLOTARG','TRODELVY','BESPONSA','SARCLISA','ISATUXIMABE','ROPOLIVY','TECVAYLI','TRUXIMA','MABTHERA','VIVAXXIA','RITUXIMABE','CYRAMZA','YERVOY','IPILIMUMABE','IMJUDO','PLATAMINE','TEVACARBO','B - PLATIN','FAULDCARBO','PARAPLATIN','CARBOPLATINA','CITOPLAX','CISPLATEX','C - PLATIN','CISPLATINA','PLATISTINE','FAULDCISPLA','OXA','OPLAT','EZULEN','EVOXALI','ELOXATIN','OXALIBBS','COLLECTRO','OXALIMEIZ','TEVAOXALI','OXALIPLATINA','KYPROLIS','CARFILZOMIBE','BELEODAQ','SPECTRILA','ASPARAGINASE','PEGASPARGASE','TRISENOX','TRIOXIDO DE ARSENIO','MEPACT','ERWINASE','HALAVEN','ERIBULINA','AREDIA','FAULDPAMI','TEORO','ZOMETA','ACLASTA','ZOLIBBS','BLAZTERE','ACIDO ZOLEDRONICO','LEUSTATIN','OFATUMUMABE','ZALTRAP','FAULDLEUCO') THEN 'EV'
        WHEN ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO IN('ONCASPAR') THEN 'EV / IM'
        WHEN ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO IN('EPREX','HEMAX','ERITROMAX','ARANESP','OCTRIDE','OCTREOTIDA','SANDOSTATIN','VIDAZA','WINDUZA','AZACITIDINA','ZOMI','ELOME','TOVAR','VERAZO','BOZORED','VELCADE','MIELOCADE','BORTEZOMIBE','LEUKINE','FIPRIMA','FILGRASTIM','FILGRASTINE','GRANULOKINE','ARAZABI') THEN 'EV / SC'
        WHEN ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO IN('ARACYTIN') THEN 'EV / SC / IT'
        WHEN ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO IN('ELIGARD','LECTRUM','LUPRON DEPOT','LEUPRORRELINA') THEN 'IM / SC'
        WHEN ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO IN('TRIPTORRELINA','NEO DECAPEPTYL','ONCO BCG','IMUNO BCG','VACINA BCG','UROHIPE BCG','MYCOBACTERIUM BOVIS','POEMMY','SELETIV','FASLODEX','SUPRENIQ','FULVESTRANTO') THEN 'IM'
        WHEN ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO IN('BACILLUS CALMETTE GUERIN LIOFILIZADO') THEN 'INTRAVESICAL'
        WHEN ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO IN('ONTRAX','GENUXAL','CICLOFOSFAMIDA','ALKERAN','MELFALANO','MELPHALAN','TEMODAL','TEMOZOLOMIDA','MTX','HYTAS','MIANTREX','METREXATO','TEVAMETHO','FAULDMETRO','METOTREXATO','EPOSIDO','EUNADES','EVOPOSDO','ETOPOSIDO','ETOPOSIDEO') THEN 'EV / VO'
        WHEN ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO IN('AKYNZEO','NETUPITANTO','CINACALCETE','BENALQ','LEUKERAN','CITOSTAL','CAPECITABINA','PURINETHOL','MERCAPTOPURINA','LANVIS','LONSURF','XELODA','CORRETAL','VEPESID','CABOMETYX','ZYKADIA','VERZENIOS','SPRYCEL','GLIVEC','GLIMATIN','LEUPHILA','IMATINIBE','TASIGNA','ICLUSIG','GIOTRIF','ALECENSA','WELIREG','TARCEVA','IRESSA','TAGRISSO','ALUNBRIG','EVOBRIG','XALKORI','LORBRENA','LORVIQUA','MEKTOVI','COTELLIC','TAFINLAR','MEKINIST','TRAMETINIBE','BRAFTOVI','KOSELUGO','ZELBORAF','IBRANCE','KISQALI','CALQUENCE','IMBRUVICA','TABRECTA','PIQRAY','INLYTA','ERFANDEL','TYKERB','VITRAKVI','LENVIMA','LENVATINIBE','RYDAPT','NERLYNX','VOTRIENT','PAZOPANIBE','STIVARGA','JAKAVI','RETEVMO','NEXAVAR','SUTENT','TEPMETKO','CAPRELSA','BRUKINSA','XOSPATA','BIOEZULEN','TRETINOINA','ACIDO TRANSRETINOICO','VESANOID','NINLARO','ERIVEDGE','ZEJULA','LYNPARZA','OLAPARIBE','LEUX','TEPEV','HYDREA','HIDROXIUREIA','LISODREN','DESTILBENOL','MEGESTAT','FEMIGESTROL','NUVYOR','REVLIMID','LENALIDOMIDA','IMNOVID','POMALID','POMALYST','NATULAN','PROCARBAZINA','VENCLEXTA','VENETOCLAX','TIBSOVO','LUMAKRAS','TACFEN','TAMOXIM','TAXOFEN','TECNOTAX','NOLVADEX D','TAMOXIFENO','MATIZ','RARIJA','ZYTIGA','ZOSTIDE','ABIRATERONA','ERLEADA','CASODEX','BICALUTAMIDA','NUBEQA','XTANDI','ARIMIDEX','ANASTROZOL','ANASTROLIBBS','PROEXTY','AROMASIN','EXEMESTANO','FEMARA','LETROZOL','VEQUILE','AFINITOR','CERTICAN','EVEROLIMO','FYARRO','OFEV','NINTEDANIBE') THEN 'VO'
        WHEN ipan.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO IN('ALFAEPOETINA','ERITROPOETINA','LANREOTIDA','SOMATULINE','PHESGO','RIXIMYO','RIXIMYO','RUXIENCE','ZOLADEX','GOSSERRELINA','ZARZIO','TEVAGRASTIM','LONQUEX','LIPEGFILGRASTIM','PELGRAZ','FULPHILA','NEULASTIM','PEGFILGRASTIM','FIRMAGON','DEGARELIX','XGEVA','PROLIA','DENOSUMABE','KESIMPTA') THEN 'SC'
        ELSE 'NAO SE APLICA'
    END AS INS_DSC_CLASSIFICACAO_VIA_ACESSO_NOVA,

    CASE -- Lógica de ESPECIALIDADE_PRIMARIA da tb_class_med_final, aplicada ao INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO
