-- 
-- CTEs TB_JUNCAO_ONCO_IMUNO, TB_ESP_MEDICAMENTO, TB_ESP_MEDICAMENTO_AJUSTAR, tb_class_med_final 
--são tabelas  especificsa que estou usando para fazer a classificação da insumo
------------------------------------------
TB_JUNCAO_ONCO_IMUNO AS
(
    SELECT DISTINCT
    COD_SERVICO_MATERIAL_MEDICAMENTO,
    DSC_SERVICO_MATERIAL_MEDICAMENTO_ORIGEM AS DSC_SERVICO_MEDICAMENTO,
    DSC_MEDICAMENTO AS DSC_PADRAO_SERVICO_MEDICAMENTO,
    DSC_PRINCIPIO_ATIVO AS DSC_PRINCIPIO_ATIVO_MEDICAMENTO,
    CASE WHEN DSC_MEDICAMENTO IN('RITUXIMABE','RIXIMYO','TRUXIMA','VIVAXXIA','MABTHERA','RUXIENCE')  THEN '1'ELSE '0' END AS FLG_VINCULO_CODIGO_TUSS,
    CASE WHEN DSC_MEDICAMENTO IN('RITUXIMABE','RIXIMYO','TRUXIMA','VIVAXXIA') THEN 'IMUNOBIOLOGICO,ONCOLOGICO'
          WHEN DSC_MEDICAMENTO IN('MABTHERA','RUXIENCE') THEN 'IMUNOBIOLOGICO,NAO EXCLUSIVO ONCOLOGIA'
    ELSE DSC_CLASSIFICACAO_MEDICAMENTO END AS DSC_CLASSIFICACAO_MEDICAMENTO,

    CASE WHEN DSC_MEDICAMENTO IN('RITUXIMABE','RIXIMYO','TRUXIMA','VIVAXXIA','MABTHERA','RUXIENCE') THEN 'IMUNOBIOLOGICO,IMUNOTERAPIA'
    ELSE DSC_SUBCLASSIFICACAO_MEDICAMENTO END AS DSC_SUBCLASSIFICACAO_MEDICAMENTO, 
    DSC_CLASSIFICACAO_VIA_ACESSO,
    DSC_TIPO_CANCER
    FROM tab

    UNION ALL

    SELECT DISTINCT
    COD_SERVICO_IMUNOBIOLOGICO AS COD_SERVICO_MATERIAL_MEDICAMENTO,
    DSC_SERVICO_IMUNOBIOLOGICO AS DSC_SERVICO_MEDICAMENTO,
    DSC_PADRAO_SERVICO_MEDICAMENTO,
    CASE WHEN DSC_PRINCIPIO_ATIVO_MEDICAMENTO = 'RUXIENCE' THEN 'RITUXIMABE'
        WHEN DSC_PRINCIPIO_ATIVO_MEDICamento =  'IMUNOGLOBULINA G' THEN 'IMUNOGLOBULINA HUMANA'ELSE DSC_PRINCIPIO_ATIVO_MEDICAMENTO END AS DSC_PRINCIPIO_ATIVO_MEDICAMENTO,
    FLG_VINCULO_CODIGO_TUSS,
    CASE WHEN DSC_PADRAO_SERVICO_MEDICAMENTO IN('RITUXIMABE','RIXIMYO','TRUXIMA','VIVAXXIA') THEN 'IMUNOBIOLOGICO,ONCOLOGICO'
          WHEN DSC_PADRAO_SERVICO_MEDICAMENTO IN('MABTHERA','RUXIENCE') THEN 'IMUNOBIOLOGICO,NAO EXCLUSIVO ONCOLOGIA'
    ELSE 'IMUNOBIOLOGICO' END AS DSC_CLASSIFICACAO_MEDICAMENTO,
    
    CASE WHEN DSC_PRINCIPIO_ATIVO_MEDICAMENTO IN('IMUNOGLOBULINA HUMANA','IMUNOGLOBULINA G') THEN 'IMUNOGLOBULINA' 
        WHEN DSC_PADRAO_SERVICO_MEDICAMENTO IN('RITUXIMABE','RIXIMYO','TRUXIMA','VIVAXXIA','MABTHERA','RUXIENCE') THEN 'IMUNOBIOLOGICO,IMUNOTERAPIA' 
    ELSE 'IMUNOBIOLOGICO' END AS DSC_SUBCLASSIFICACAO_MEDICAMENTO,
    CASE WHEN DSC_PADRAO_SERVICO_MEDICAMENTO IN('MABTHERA','RITUXIMABE','TRUXIMA','VIVAXXIA') THEN  'EV'
        WHEN DSC_PADRAO_SERVICO_MEDICAMENTO IN('RUXIENCE','RIXIMYO') THEN 'SC' 
    ELSE '' END AS DSC_CLASSIFICACAO_VIA_ACESSO,
    'NAO MAPEADO' AS DSC_TIPO_CANCER
    FROM tab
  --39.394
)
,TB_ESP_MEDICAMENTO AS
(
  SELECT
  COD_SERVICO_MATERIAL_MEDICAMENTO,
  DSC_SERVICO_MEDICAMENTO,
  DSC_PADRAO_SERVICO_MEDICAMENTO,
  DSC_PRINCIPIO_ATIVO_MEDICAMENTO,
  MAX(FLG_VINCULO_CODIGO_TUSS) AS FLG_VINCULO_CODIGO_TUSS,
  STRING_AGG(DISTINCT DSC_CLASSIFICACAO_MEDICAMENTO ORDER BY DSC_CLASSIFICACAO_MEDICAMENTO) AS DSC_CLASSIFICACAO_MEDICAMENTO,
  STRING_AGG(DISTINCT DSC_SUBCLASSIFICACAO_MEDICAMENTO ORDER BY DSC_SUBCLASSIFICACAO_MEDICAMENTO) AS DSC_SUBCLASSIFICACAO_MEDICAMENTO,
  STRING_AGG(DISTINCT DSC_CLASSIFICACAO_VIA_ACESSO ,'' ORDER BY DSC_CLASSIFICACAO_VIA_ACESSO) AS DSC_CLASSIFICACAO_VIA_ACESSO,
  STRING_AGG(DISTINCT DSC_TIPO_CANCER ,'' ORDER BY DSC_TIPO_CANCER) AS DSC_CLASSIFICACAO_TIPO_CANCER
  FROM TB_JUNCAO_ONCO_IMUNO
  GROUP BY ALL
)
,TB_ESP_MEDICAMENTO_AJUSTAR AS
(
  SELECT
  COD_SERVICO_MATERIAL_MEDICAMENTO,
  DSC_SERVICO_MEDICAMENTO,
  DSC_PADRAO_SERVICO_MEDICAMENTO,
  DSC_PRINCIPIO_ATIVO_MEDICAMENTO,
  FLG_VINCULO_CODIGO_TUSS,
  DSC_CLASSIFICACAO_MEDICAMENTO,
  CASE 
      WHEN DSC_CLASSIFICACAO_MEDICAMENTO IN('ONCOLOGICO','ADJUVANTE','SUPORTE','NAO EXCLUSIVO ONCOLOGIA') THEN 'ONCOLOGIA'
      WHEN DSC_CLASSIFICACAO_MEDICAMENTO = 'IMUNOBIOLOGICO' THEN 'IMUNOBIOLOGICO'
      WHEN DSC_CLASSIFICACAO_MEDICAMENTO IN('IMUNOBIOLOGICO,ONCOLOGICO','IMUNOBIOLOGICO,NAO EXCLUSIVO ONCOLOGIA') THEN 'IMUNOBIOLOGICO E ONCOLOGIA' 
  END AS DSC_CLASSIFICACAO_MEDICAMENTO_AGRUPADO,
  DSC_SUBCLASSIFICACAO_MEDICAMENTO AS DSC_PADRAO_CLASSIFICACAO_MEDICAMENTO, 
  DSC_CLASSIFICACAO_VIA_ACESSO,
  DSC_CLASSIFICACAO_TIPO_CANCER
  FROM TB_ESP_MEDICAMENTO 
 --38616
)
