    mcf.INS_DSC_MEDICAMENTO_REF,
    
    mcf.INS_DSC_CLASSIFICACAO_MEDICAMENTO_NOVA AS nao_espec_CLASSIF_MEDICAMENTO,
    acf.DSC_CLASSIFICACAO_MEDICAMENTO_NOVA AS especifica_CLASSIF_MEDICAMENTO,
    
    mcf.INS_DSC_CLASSIFICACAO_VIA_ACESSO_NOVA AS nao_espec_VIA_ACESSO,
    acf.DSC_CLASSIFICACAO_VIA_ACESSO_NOVA AS especifica_VIA_ACESSO,
    
    mcf.INS_ESPECIALIDADE_PRIMARIA AS nao_espec_ESPEC_PRIMARIA,
    acf.ESPECIALIDADE_PRIMARIA AS especifica_ESPEC_PRIMARIA,
    
    mcf.INS_ESPECIALIDADE_SECUNDARIA AS nao_espec_ESPEC_SECUNDARIA,
    acf.ESPECIALIDADE_SECUNDARIA AS especifica_ESPEC_SECUNDARIA,
    
    -- Flags de divergência para cada campo
    CASE WHEN IFNULL(mcf.INS_DSC_CLASSIFICACAO_MEDICAMENTO_NOVA, '') != IFNULL(acf.DSC_CLASSIFICACAO_MEDICAMENTO_NOVA, '') THEN TRUE ELSE FALSE END AS DIV_CLASSIF_MEDICAMENTO,
    CASE WHEN IFNULL(mcf.INS_DSC_CLASSIFICACAO_VIA_ACESSO_NOVA, '') != IFNULL(acf.DSC_CLASSIFICACAO_VIA_ACESSO_NOVA, '') THEN TRUE ELSE FALSE END AS DIV_VIA_ACESSO,
    CASE WHEN IFNULL(mcf.INS_ESPECIALIDADE_PRIMARIA, '') != IFNULL(acf.ESPECIALIDADE_PRIMARIA, '') THEN TRUE ELSE FALSE END AS DIV_ESPEC_PRIMARIA,
    CASE WHEN IFNULL(mcf.INS_ESPECIALIDADE_SECUNDARIA, '') != IFNULL(acf.ESPECIALIDADE_SECUNDaria, '') THEN TRUE ELSE FALSE END AS DIV_ESPEC_SECUNDARIA,

    acf.COD_SERVICO_MATERIAL_MEDICAMENTO AS especifica_COD_SERVICO, -- Para verificar se houve match
    acf.DSC_PRINCIPIO_ATIVO_MEDICAMENTO AS especifica_PRINCIPIO_ATIVO,
    acf.DSC_PADRAO_SERVICO_MEDICAMENTO AS especifica_PADRAO_MEDICAMENTO

FROM nao_espec_classificacao_final mcf
LEFT JOIN especifica_classificacao_final acf 
    ON CAST(mcf.COD_TUSS_CONSOLIDADO__c AS STRING) = CAST(acf.COD_SERVICO_MATERIAL_MEDICAMENTO AS STRING)
    AND mcf.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO = acf.DSC_PRINCIPIO_ATIVO_MEDICAMENTO
   
)
-- CTE PARA DAR PREFERENCIA A TABELA DA ADRINA QUANDO O CODIGO TUSS For O Mesmo
, consolidacao_com_prioridade AS (
SELECT
    comp.COD_TUSS_CONSOLIDADO__c,
    comp.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO,
    comp.INS_DSC_MEDICAMENTO_REF,

    -- Classificação de Medicamento Final
    CASE 
        WHEN comp.especifica_COD_SERVICO IS NOT NULL AND comp.especifica_CLASSIF_MEDICAMENTO IS NOT NULL AND comp.DIV_CLASSIF_MEDICAMENTO = TRUE
        THEN comp.especifica_CLASSIF_MEDICAMENTO
        ELSE comp.nao_espec_CLASSIF_MEDICAMENTO
    END AS CLASSIFICACAO_MEDICAMENTO_CONSOLIDADA,

    -- Via de Acesso Final
    CASE 
        WHEN comp.especifica_COD_SERVICO IS NOT NULL AND comp.especifica_VIA_ACESSO IS NOT NULL AND comp.DIV_VIA_ACESSO = TRUE
        THEN comp.especifica_VIA_ACESSO
        ELSE comp.nao_espec_VIA_ACESSO
    END AS VIA_ACESSO_CONSOLIDADA,

    -- Especialidade Primária Final
    CASE 
        WHEN comp.especifica_COD_SERVICO IS NOT NULL AND comp.especifica_ESPEC_PRIMARIA IS NOT NULL AND comp.DIV_ESPEC_PRIMARIA = TRUE
        THEN comp.especifica_ESPEC_PRIMARIA
        ELSE comp.nao_espec_ESPEC_PRIMARIA
    END AS ESPEC_PRIMARIA_CONSOLIDADA,

    -- Especialidade Secundária Final
    CASE 
        WHEN comp.especifica_COD_SERVICO IS NOT NULL AND comp.especifica_ESPEC_SECUNDARIA IS NOT NULL AND comp.DIV_ESPEC_SECUNDARIA = TRUE
        THEN comp.especifica_ESPEC_SECUNDARIA
        ELSE comp.nao_espec_ESPEC_SECUNDARIA
    END AS ESPEC_SECUNDARIA_CONSOLIDADA,
    comp.nao_espec_CLASSIF_MEDICAMENTO,
    comp.especifica_CLASSIF_MEDICAMENTO,
    comp.DIV_CLASSIF_MEDICAMENTO,
    comp.nao_espec_VIA_ACESSO,
    comp.especifica_VIA_ACESSO,
    comp.DIV_VIA_ACESSO,
    comp.nao_espec_ESPEC_PRIMARIA,
    comp.especifica_ESPEC_PRIMARIA,
    comp.DIV_ESPEC_PRIMARIA,
    comp.nao_espec_ESPEC_SECUNDARIA,
    comp.especifica_ESPEC_SECUNDARIA,
    comp.DIV_ESPEC_SECUNDARIA,
    comp.especifica_COD_SERVICO 
FROM comparacao_classificacoes comp
),
-------------------------------------------------------------------------------------------------------------------------------------
tab_insumo_final AS (SELECT distinct
    COD_TUSS_CONSOLIDADO__c,
    INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO,
    --INS_DSC_MEDICAMENTO_REF,
    CLASSIFICACAO_MEDICAMENTO_CONSOLIDADA,
    --VIA_ACESSO_CONSOLIDADA,
    ESPEC_PRIMARIA_CONSOLIDADA,
    --ESPEC_SECUNDARIA_CONSOLIDADA,
    
    -- colunas da comp pra verificar mudançdas
    -- nao_espec_CLASSIF_MEDICAMENTO,
    -- especifica_CLASSIF_MEDICAMENTO,
    -- DIV_CLASSIF_MEDICAMENTO,
    -- nao_espec_VIA_ACESSO,
    -- especifica_VIA_ACESSO,
    -- DIV_VIA_ACESSO,
    -- nao_espec_ESPEC_PRIMARIA,
    -- especifica_ESPEC_PRIMARIA,
    -- DIV_ESPEC_PRIMARIA,
    -- nao_espec_ESPEC_SECUNDARIA,
    -- especifica_ESPEC_SECUNDARIA,
    -- DIV_ESPEC_SECUNDARIA,
    -- especifica_COD_SERVICO 
    
FROM consolidacao_com_prioridade
WHERE 1=1
--AND DIV_CLASSIF_MEDICAMENTO = TRUE 
--AND especifica_COD_SERVICO IS NULL and CLASSIFICACAO_MEDICAMENTO_CONSOLIDADA = 'REVER'
ORDER BY 
    COD_TUSS_CONSOLIDADO__c, 
    INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO),
-------------------------------------------------------------
--fim da comparação e agregação 
-------------------------------------------------------------
-- trazendo contas pagas 
SINISTRO AS (
  SELECT DISTINCT FLG_INTERNACAO,
  CAST(CONCAT(CAST(COD_DOCUMENTO_SINISTRO AS STRING),CAST(COD_COMPLEMENTO_SINISTRO AS STRING),
  CAST(COD_ORIGEM_PRESTADOR AS STRING),CAST(COD_SEQUENCIA_SINISTRO AS STRING),
  CAST(COD_ANEXO_ITEM_SERVICO_SINISTRO AS STRING),CAST(COD_ITEM_SERVICO_SINISTRO AS STRING)) AS STRING) AS COD_CHAVE_MAT_MED,
  FROM tab
  WHERE 1=1
)
------
,contas as(
SELECT 
COD_SERVICO_TUSS_CONSOLIDADO,
COD_SERVICO_MATERIAL_MEDICAMENTO as cod_servico,
COUNT(DISTINCT NUM_VPP) qnt_num_vpp,
SUM(VAL_PAGO_MATERIAL_MEDICAMENTO) VLR_PAGO_SERVICO , 
FROM
tab ITEM
LEFT JOIN SINISTRO
    ON CAST(CONCAT(CAST(COD_DOCUMENTO_SINISTRO AS STRING),CAST(COD_COMPLEMENTO_SINISTRO AS STRING),
    CAST(COD_ORIGEM_PRESTADOR AS STRING),CAST(COD_SEQUENCIA_SINISTRO AS STRING),
    CAST(COD_ANEXO_ITEM_SERVICO_SINISTRO AS STRING),CAST(COD_ITEM_SERVICO_SINISTRO AS STRING)) AS STRING) = SINISTRO.COD_CHAVE_MAT_MED

WHERE 1=1
AND DSC_SUB_GRUPO_SERVICO = 'MEDICAMENTO'
AND SINISTRO.FLG_INTERNACAO = 'N'
AND EXTRACT(YEAR FROM DAT_EXECUCAO_SINISTRO) = 2024
-- AND  COD_SERVICO_TUSS_CONSOLIDADO = '-2'
GROUP BY ALL
)
--select sum(VLR_PAGO_SERVICO) from contas 3,2 bi 
-------------
,tab_final as(
SELECT insumo.COD_TUSS_CONSOLIDADO__c,
insumo.INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO,
insumo.ESPEC_PRIMARIA_CONSOLIDADA ,
contas.qnt_num_vpp,
VLR_PAGO_SERVICO
FROM tab_insumo_final insumo 
inner JOIN contas 
ON lpad(cast(insumo.COD_TUSS_CONSOLIDADO__c as string),8,'0') = lpad(cast(contas.COD_SERVICO_TUSS_CONSOLIDADO as string),8,'0')
),
tb_final_ as (SELECT 
COD_TUSS_CONSOLIDADO__c,
INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO,
ESPEC_PRIMARIA_CONSOLIDADA ,
qnt_num_vpp,
VLR_PAGO_SERVICO --VAL_PAGO
FROM tab_final
group by all )
select COD_TUSS_CONSOLIDADO__c,INS_DSC_PRINCIPIO_ATIVO_NORMALIZADO,
       ESPEC_PRIMARIA_CONSOLIDADA,qnt_num_vpp,
       VLR_PAGO_SERVICO--sum(VLR_PAGO_SERVICO) --3,1 bi 
 from tb_final_ --where COD_TUSS_CONSOLIDADO__c = '90423380' 
